CREATE TABLE `security_portfolio_executions` (`id` text PRIMARY KEY NOT NULL,`portfolio_id` text NOT NULL,`tenant_id` text NOT NULL,`delivery_owner` text NOT NULL,`budget_baseline` text NOT NULL,`target_date` text NOT NULL,`milestones_json` text NOT NULL,`progress` integer DEFAULT 0 NOT NULL,`actual_spend` text,`variance_note` text,`delivery_evidence` text,`benefit_metric` text NOT NULL,`benefit_result` text,`status` text NOT NULL,`started_by` text NOT NULL,`started_at` text NOT NULL,`updated_by` text,`updated_at` text,`submitted_by` text,`submitted_at` text,`verified_by` text,`verified_at` text,`verification_note` text);
CREATE UNIQUE INDEX `security_portfolio_executions_portfolio_id_unique` ON `security_portfolio_executions` (`portfolio_id`);
CREATE INDEX `security_portfolio_executions_tenant_status_idx` ON `security_portfolio_executions` (`tenant_id`,`status`);
CREATE INDEX `security_portfolio_executions_target_idx` ON `security_portfolio_executions` (`tenant_id`,`target_date`);
